import math

def logsumexp(xs):
 m=max(xs)
 return m+math.log(sum(math.exp(x-m) for x in xs))
def epsilon(z,q,T,delta=1e-9):
 vals=[]
 for a in range(2,129):
  logs=[math.lgamma(a+1)-math.lgamma(k+1)-math.lgamma(a-k+1)+(a-k)*math.log1p(-q)+k*math.log(q)+(k*k-k)/(2*z*z) for k in range(a+1)]
